for(let g of globals){
  let v=globalThis[g];
  console.log("GLOBAL",g,typeof v);
  if(typeof v==="function"){
    console.log("  ctor props:",names(v));
    if(v.prototype) console.log("  proto:",names(v.prototype));
  } else if(v && typeof v==="object"){
    console.log("  props:",names(v));
  }
}
