#!/usr/bin/env python3
# Independent reimplementation of the qjs command-line JavaScript shell
# (behaviorally compatible with the bundled reference, written from scratch).
import sys, os, re, math, time, struct, signal, threading, unicodedata
import traceback as _traceback

VERSION = "2025-09-13"

# --------------------------------------------------------------------------
# JS primitive singleton values / small helper types

class UndefinedType:
    __slots__ = ()
    def __repr__(self): return "undefined"
    def __bool__(self): return False
class NullType:
    __slots__ = ()
    def __repr__(self): return "null"
    def __bool__(self): return False
UNDEFINED = UndefinedType()
NULL = NullType()

class EmptyCompletion:
    __slots__ = ()
EMPTY = EmptyCompletion()

class JSSymbol:
    __slots__ = ("desc",)
    def __init__(self, desc=None):
        self.desc = desc  # JS string (code-unit str) or None
    def __repr__(self):
        return f"Symbol({self.desc!r})"

class JSPrivateName:
    __slots__ = ("desc",)
    def __init__(self, desc): self.desc = desc
    def __repr__(self): return f"Private({self.desc})"

# Global symbol registry: key (python scalar str) -> JSSymbol ; reverse id->key
_symbol_registry = {}
_symbol_registry_rev = {}

def js_str_from_py(s):
    """Convert a normal Python string to a JS code-unit string."""
    if s is None:
        return None
    out = []
    for ch in s:
        o = ord(ch)
        if o > 0xFFFF:
            o -= 0x10000
            out.append(chr(0xD800 + (o >> 10)))
            out.append(chr(0xDC00 + (o & 0x3FF)))
        else:
            out.append(ch)
    return "".join(out)

def py_str_from_js(s):
    """Combine surrogate pairs in a JS code-unit string into scalars."""
    if s is None:
        return None
    out = []
    i = 0
    n = len(s)
    while i < n:
        o = ord(s[i])
        if 0xD800 <= o <= 0xDBFF and i + 1 < n:
            o2 = ord(s[i+1])
            if 0xDC00 <= o2 <= 0xDFFF:
                out.append(chr(0x10000 + ((o - 0xD800) << 10) + (o2 - 0xDC00)))
                i += 2
                continue
        out.append(s[i])
        i += 1
    return "".join(out)

def encode_out(s):
    return py_str_from_js(s).encode("utf-8", "surrogatepass")

def _write_stream(fd, text):
    try:
