# Number formatting (ECMAScript Number::toString)

def _shortest_digits_exp(x):
    """Return (digits_str_without_dot, n) such that x = digits * 10^(n-len(digits)),
    using Python's shortest repr for the digit sequence. x > 0 finite."""
    r = repr(x)
    # repr forms: '123.456', '1e+16', '1.5e-07', '5e-324', '100.0'
    if "e" in r or "E" in r:
        mant, exp_s = r.replace("E", "e").split("e")
        exp = int(exp_s)
        if "." in mant:
            ip, fp = mant.split(".")
            digits = ip + fp
            # value = digits * 10^(exp - len(fp))  ; n satisfies value=digits*10^(n-len(digits))
            n = exp - len(fp) + len(digits)
            # n = position of decimal point: value = 0.digits * 10^n ? check below formula approach
            # Use standard: s=digits int, k=len, value = s * 10^(n-k)
            # exp form: value = mant *10^exp, mant = digits *10^(-len(fp))
            # so n-k = exp-len(fp) -> n = exp - len(fp) + k = exp + len(ip)
            n = exp + len(ip)
        else:
            digits = mant
            n = exp + len(mant)
        digits = digits.lstrip("0") or "0"
        return digits.rstrip("0") or "0", n
    else:
        if "." in r:
            ip, fp = r.split(".")
        else:
            ip, fp = r, ""
        if ip != "0":
            digits = (ip + fp)
            n = len(ip)
        else:
            # 0.000ddd
            i = 0
            while i < len(fp) and fp[i] == "0":
                i += 1
            digits = fp[i:]
            n = -i
        digits = digits.rstrip("0") or "0"
        return digits, n

def number_to_string(x):
    if isinstance(x, bool):
        x = 1.0 if x else 0.0
    x = float(x)
    if math.isnan(x):
        return "NaN"
    if x == 0:
        return "0"
    if math.isinf(x):
        return "Infinity" if x > 0 else "-Infinity"
    neg = x < 0
    s, n = _shortest_digits_exp(abs(x))
    k = len(s)
    if k <= n <= 21:
        out = s + "0" * (n - k)
    elif 0 < n <= 21:
        out = s[:n] + "." + s[n:]
    elif -6 < n <= 0:
        out = "0." + "0" * (-n) + s
    else:
        if k == 1:
            mant = s
        else:
            mant = s[0] + "." + s[1:]
        e = n - 1
        out = mant + "e" + ("+" if e >= 0 else "-") + str(abs(e))
    return ("-" if neg else "") + out

def number_to_radix_string(x, radix):
    if math.isnan(x): return "NaN"
    if math.isinf(x): return "Infinity" if x > 0 else "-Infinity"
    if x == 0: return "0"
    digits_chars = "0123456789abcdefghijklmnopqrstuvwxyz"
    neg = x < 0
    x = abs(x)
    # integer part
    int_part = math.floor(x)
    frac = x - int_part
    if int_part == 0:
        int_str = "0"
    else:
        parts = []
        v = int_part
        # v can be >2**53; convert via exact int of the double
        vi = int(v)  # float is integral in this range semantics; int() exact for doubles
        while vi > 0:
            parts.append(digits_chars[vi % radix])
            vi //= radix
        int_str = "".join(reversed(parts))
    if frac == 0:
        return ("-" if neg else "") + int_str
    # fractional digits: exact expansion of the dyadic rational
    from fractions import Fraction
    fr = Fraction(x) - Fraction(int(int_part)) if int_part==int(int_part) else Fraction(x)
    # Fraction(float) is exact
    fr = Fraction(x)
    fr -= int(fr)
    frac_digits = []
    seen_limit = 0
    while fr > 0 and seen_limit < 1200:
        fr *= radix
        d = int(fr)
        frac_digits.append(digits_chars[d])
        fr -= d
        seen_limit += 1
        if seen_limit > 200 and radix not in (2,4,8,16,32):
            # non-terminating in odd bases: truncate when remaining value
            # is below double precision relative to produced length
            break
    return ("-" if neg else "") + int_str + "." + "".join(frac_digits)

