def string_to_number(s):
    t=s.strip(JS_WS)
    if t=="": return 0.0
    if t.startswith(("0x","0X")):
        try:
            if all(c in "0123456789abcdefABCDEF" for c in t[2:]) and len(t)>2: return float(int(t[2:],16))
        except Exception: pass
        return math.nan
    if t.startswith(("0b","0B")):
        if len(t)>2 and all(c in "01" for c in t[2:]): return float(int(t[2:],2))
        return math.nan
    if t.startswith(("0o","0O")):
        if len(t)>2 and all(c in "01234567" for c in t[2:]): return float(int(t[2:],8))
        return math.nan
    if not _NUMSTR_RE.match(t): return math.nan
    try: return float(t)
