def string_to_bigint(s):
    t=s.strip(JS_WS)
    if t=="": return 0
    sign=1
    body=t
    if body[:1] in ("+","-"):
        if body[0]=="-": sign=-1
        body=body[1:]
        # non-decimal with sign is invalid
        if body.startswith(("0x","0X","0b","0B","0o","0O")): return None
    try:
        if body.startswith(("0x","0X")):
            if len(body)<=2 or not all(c in "0123456789abcdefABCDEF" for c in body[2:]): return None
            return int(body[2:],16)
        if body.startswith(("0b","0B")):
            if len(body)<=2 or not all(c in "01" for c in body[2:]): return None
            return int(body[2:],2)
        if body.startswith(("0o","0O")):
            if len(body)<=2 or not all(c in "01234567" for c in body[2:]): return None
            return int(body[2:],8)
        if not body.isdigit(): return None
        return sign*int(body,10)
    except Exception:
        return None
