    if isinstance(key,JSSymbol):
        desc=key.desc or ""
        return desc if _is_ascii_ident(desc) else _quote_js_string(desc)
    if isinstance(key,str):
        if key=="0" or (key and key[0] in "123456789" and all(c.isdigit() and c.isascii() for c in key)):
            return key
        if _is_ascii_ident(key): return key
        return _quote_js_string(key)
    return str(key)

