            width=int(fmt[j:i])
        precision=None
        if i<n and fmt[i]==".":
            i+=1
            if i<n and fmt[i]=="*":
                pv=next_arg(); precision=itp.to_int32(pv); i+=1
                if precision<0: precision=None
            elif i<n and fmt[i].isdigit():
