def _run_module_and_events(itp,rec):
    p=itp._evaluate_module(rec)
    if isinstance(p,JSObject) and p.kind=="promise":
        if p.internal.get("state")=="rejected":
            itp._dump_error_value(p.internal.get("value"))
            return 1
        while p.internal.get("state")=="pending":
            itp.drain_microtasks()
            if p.internal.get("state")!="pending": break
            if itp.timers or itp.read_handlers or itp.write_handlers:
                itp._poll_event()
            elif itp.microtasks:
                continue
            else:
                break
        if p.internal.get("state")=="rejected":
            itp._dump_error_value(p.internal.get("value"))
            return 1
    return itp.run_event_loop()

def _cli_main_impl(argv):
