    def do_help():
        write_stdout(HELP_TEXT); raise _CliExit(1)
    def unknown(opt):
        write_stderr(f"qjs: unknown option '{opt}'\n"); do_help()
    try:
        i=0
        while i<len(args):
            arg=args[i]
            if arg=="--":
                i+=1
