                    opts["script_args"]=args[i:]
                elif i<len(args):
                    opts["filename"]=args[i]; opts["script_args"]=args[i:]
                break
            if arg.startswith("-") and arg!="-":
                if arg.startswith("--"):
                    if arg in ("--help",): do_help()
                    elif arg in ("--eval",):
                        i+=1
                        if i>=len(args):
                            write_stderr("qjs: missing expression for -e\n"); return 2
                        opts["expr"]=args[i]
                    elif arg=="--interactive": opts["interactive"]=True
                    elif arg=="--module": opts["module"]=1
                    elif arg=="--script": opts["module"]=0
                    elif arg=="--strict": opts["strict"]=True
                    elif arg=="--include":
                        i+=1
                        if i>=len(args):
                            write_stderr("expecting filename"); return 1
                        opts["includes"].append(args[i])
                    elif arg=="--std": opts["std"]=True
                    elif arg=="--trace": opts["trace"]=True
                    elif arg=="--dump": opts["dump"]=True
                    elif arg=="--memory-limit":
                        i+=1
                        if i>=len(args):
