            try:
                if opts["module"]==1:
                    rec=interp._load_module_from_source(opts["expr"],"<cmdline>",is_main=True)
                    interp._instantiate_module(rec)
                    main_module_rec=rec
                else:
                    prog=interp.parse(opts["expr"],"<cmdline>",is_module=False,strict=strict)
                    interp.run_script_program(prog,"<cmdline>")
