def _finish(interp,rc,opts):
    if rc==0 and opts.get("dump"):
        _dump_memory(interp,opts.get("memory_limit",0))
    return rc

def _run_worker(path,fd):
    import socket as _socket
    try:
        sock=_socket.socket(fileno=fd)
    except Exception:
        sock=None
    interp=Interp({"is_worker":True,"script_args":[]})
    global _ACTIVE_INTERP
    _ACTIVE_INTERP=interp
    interp.worker_socket=sock
    # worker globals have no scriptArgs
    interp.global_obj.props.pop("scriptArgs",None)
    try:
        resolved=os.path.realpath(path)
        src=_load_source(path)
        if src is None: return 1
        rec=interp._load_module_from_source(src,resolved,is_main=True)
        interp._instantiate_module(rec)
