def _repl_level(source):
    stack=[]  # entries char or ('string',q) etc represented as display char
    i=0; n=len(source); state=None
    # states: None, ('str',quote), ('tpl',), ('linecomment',), ('blockcomment',), ('regex',inclass)
    # Stack entries are dicts {ch: display, kind}
    tpl_depths=[]
    last_sig=""
    while i<n:
        ch=source[i]
        if state is not None:
            typ=state[0]
            if typ=="str":
                if ch=="\\": i+=2; continue
                if ch==state[1]: state=None; stack.pop() if stack and stack[-1].get("state") else None
                i+=1; continue
            if typ=="tpl":
                if ch=="\\": i+=2; continue
                if ch=="`": state=None; stack.pop() if stack and stack[-1].get("state") else None; i+=1; continue
                if ch=="$" and i+1<n and source[i+1]=="{":
                    stack.append({"ch":"{","kind":"tplbrace"})
                    state=None; i+=2; continue
                i+=1; continue
            if typ=="linecomment":
                if ch in "\n\r": state=None
                i+=1; continue
            if typ=="blockcomment":
                if ch=="*" and i+1<n and source[i+1]=="/":
                    state=None; stack.pop() if stack and stack[-1].get("state") else None; i+=2; continue
                i+=1; continue
            if typ=="regex":
                in_class=state[1]
                if ch=="\\": i+=2; continue
                if ch=="[": state=("regex",True)
                elif ch=="]": state=("regex",False)
                elif ch=="/" and not in_class: state=None
                elif ch in "\n\r": state=None
                i+=1; continue
        # normal
        if ch in " \t\r\n":
            i+=1; continue
        if ch=="/" and i+1<n and source[i+1]=="/":
            state=("linecomment",); i+=2; continue
        if ch=="/" and i+1<n and source[i+1]=="*":
            stack.append({"ch":"/","kind":"block","state":True}); state=("blockcomment",); i+=2; continue
        if ch in "'\"":
            stack.append({"ch":ch,"kind":"str","state":True}); state=("str",ch); i+=1; last_sig="x"; continue
        if ch=="`":
            stack.append({"ch":"`","kind":"tpl","state":True}); state=("tpl",); i+=1; last_sig="x"; continue
        if ch=="/":
            # regex if last significant token suggests expression expected
            if last_sig in ("","(","[","{",",",";",":","?","=","+","-","*","%","!","~","&","|","^","<",">"):
                state=("regex",False); i+=1; last_sig="x"; continue
            last_sig="/"; i+=1; continue
        if ch in "([{":
            stack.append({"ch":ch,"kind":"brace"}); last_sig=ch; i+=1; continue
        if ch in ")]}":
            pairs={")":"(","}":"{","]":"["}
