    while i<n:
        ch=source[i]
        if state is not None:
            typ=state[0]
            if typ=="str":
                if ch=="\\": i+=2; continue
                if ch==state[1]: state=None; stack.pop() if stack and stack[-1].get("state") else None
                i+=1; continue
            if typ=="tpl":
