                if ch=="$" and i+1<n and source[i+1]=="{":
                    stack.append({"ch":"{","kind":"tplbrace"})
                    state=None; i+=2; continue
                i+=1; continue
            if typ=="linecomment":
                if ch in "\n\r": state=None
                i+=1; continue
            if typ=="blockcomment":
                if ch=="*" and i+1<n and source[i+1]=="/":
                    state=None; stack.pop() if stack and stack[-1].get("state") else None; i+=2; continue
                i+=1; continue
            if typ=="regex":
                in_class=state[1]
                if ch=="\\": i+=2; continue
                if ch=="[": state=("regex",True)
                elif ch=="]": state=("regex",False)
                elif ch=="/" and not in_class: state=None
