{"command":"cat > /tmp/edge1.js << 'JS'
let tests=[];
function t(name,fn){try{tests.push(name+":"+fn())}catch(e){tests.push(name+":ERR:"+e.message)}}
t("array-from-string",()=>Array.from("a😀b").length);
t("spread-string",()=>[..."a😀b"].length);
t("object-is",()=>Object.is(0,-0)+"/"+Object.is(NaN,NaN));
t("string-at",()=>"abc".at(-4));
t("array-with-neg",()=>[1,2].with(-1,9).join());
t("splice-neg",()=>{let a=[1,2,3]; a.splice(-1,1); return a.join()});
t("fill-neg",()=>[1,2,3].fill(0,-2,-1).join());
t("copyWithin",()=>[1,2,3,4,5].copyWithin(0,3).join());
t("flat-inf",()=>[1,[2,[3,[4]]]].flat(Infinity).join());
t("findLast",()=>[1,2,3].findLast(x=>x<3));
t("groupByKeys",()=>Object.keys(Object.groupBy([1,2,3],x=>x%2)).sort().join());
t("map-getOrInsertComputed",()=>new Map().getOrInsertComputed('k',k=>k+'!'));
t("set-symdiff",()=>[...new Set([1,2]).symmetricDifference(new Set([2,3]))].sort().join());
t("weakmap-getOrInsert",()=>{let k={}; return new WeakMap().getOrInsert(k,5)});
t("string-matchAll-lazy",()=>{let it='a1b2'.matchAll(/\d/g); return it.next().value[0]});
t("replace-function-groups",()=>"2024-01".replace(/(?<y>\d+)-(?<m>\d+)/,(m,y,mo,off,s,g)=>g.y));
t("regexp-indices-groups",()=>{let m=/(?<a>b)/d.exec('ab'); return m.indices.groups.a.join()});
t("date-setYear",()=>{let d=new Date(Date.UTC(2020,0,1)); d.setYear(99); return d.getUTCFullYear()});
t("number-epsilon",()=>Number.EPSILON);
t("bigint-tostring-radix",()=>(255n).toString(16));
t("symbol-registry",()=>Symbol.keyFor(Symbol.for('zz')));
t("reflect-ownKeys",()=>Reflect.ownKeys({a:1, [Symbol('s')]:2}).map(String).join());
t("proxy-getPrototypeOf",()=>Object.getPrototypeOf(new Proxy([],{}))===Array.prototype);
t("typed-of",()=>Int8Array.of(1,2,300).join());
t("typed-from-map",()=>Uint8Array.from([1,2],x=>x*3).join());
t("dataview-float16",()=>{let d=new DataView(new ArrayBuffer(2)); d.setFloat16(0,2.5); return d.getFloat16(0)});
t("atomics-xchg",()=>{let a=new Int16Array([5]); return Atomics.exchange(a,0,9)+"/"+a[0]});
t("iterator-helper-every",()=>[1,2,3].values().every(x=>x>0));
t("iterator-helper-reduce-init",()=>[1,2].values().reduce((a,b)=>a+b,100));
t("json-raw-in-array",()=>JSON.stringify([JSON.rawJSON('true')]));
t("error-cause",()=>new Error('outer',{cause:new Error('inner')}).cause.message);
t("aggregate-errors",()=>new AggregateError([1,2]).errors.length);
t("promise-try-args",()=>Promise.try((a,b)=>a+b,2,3) instanceof Promise);
t("string-raw-tag",()=>eval("String.raw`a\\nb`"));
t("class-extends-function",()=>{class C extends function(){this.x=1}{} return new C().x});
t("object-create-props",()=>{let o=Object.create(null,{x:{value:3,enumerable:true}}); return o.x});
t("array-hole-in",()=>1 in [,,]);
t("string-wellformed-replace",()=>"\uD800".toWellFormed().charCodeAt(0));
t("float16round",()=>Math.f16round(1.1));
t("sumPrecise",()=>Math.sumPrecise([1e20,1,-1e20]));
for(let r of tests) console.log(r);
(new Promise(r=>r(1))).then(v=>console.log("async-last",v));
JS
diff <(timeout 5 ./executable /tmp/edge1.js 2>&1) <(timeout 5 /tmp/ours /tmp/edge1.js 2>&1) && echo EDGE_MATCH"}

